import{_ as t,a,c as o,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · Lesson 124 Who, whom, which and that","description":"学习 关系代词作宾语，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 124 Who, whom, which and that","description":"学习 关系代词作宾语，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 关系代词作宾语，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 123 A trip to Australia","link":"/life/english/new-concept/book-1/unit-06/lesson-123"},"next":{"text":"第一册：英语初阶 · Lesson 125 Tea for two","link":"/life/english/new-concept/book-1/unit-06/lesson-125"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 123 A trip to Australia","link":"/life/english/new-concept/book-1/unit-06/lesson-123"},"next":{"text":"第一册：英语初阶 · Lesson 125 Tea for two","link":"/life/english/new-concept/book-1/unit-06/lesson-125"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-06/lesson-124.md","filePath":"life/english/new-concept/book-1/unit-06/lesson-124.md"}'),n={name:"life/english/new-concept/book-1/unit-06/lesson-124.md"};function h(r,e,l,s,d,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="第一册-英语初阶-·-lesson-124-who-whom-which-and-that" tabindex="-1">第一册：英语初阶 · Lesson 124 Who, whom, which and that <a class="header-anchor" href="#第一册-英语初阶-·-lesson-124-who-whom-which-and-that" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 124 Who, whom, which and that&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元 6</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-123">配套课 Lesson 123</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>讲述旅行中见到的人与事物 本课要掌握关系代词作宾语，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>travel</td><td>/ˈtrævl/</td><td>v.</td><td>旅行</td><td>travel abroad</td></tr><tr><td>during</td><td>/ˈdjʊərɪŋ/</td><td>prep.</td><td>在……期间</td><td>during the trip</td></tr><tr><td>photograph</td><td>/ˈfəʊtəɡrɑːf/</td><td>n.</td><td>照片</td><td>take a photograph</td></tr><tr><td>village</td><td>/ˈvɪlɪdʒ/</td><td>n.</td><td>村庄</td><td>visit a village</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>the place we visited — 宾语关系代词可省略</li><li>during the journey — 旅程期间</li></ul><h2 id="语法讲解-关系代词作宾语" tabindex="-1">语法讲解：关系代词作宾语 <a class="header-anchor" href="#语法讲解-关系代词作宾语" aria-label="Permalink to &quot;语法讲解：关系代词作宾语&quot;">​</a></h2><p>在限制性定语从句中，关系代词若作宾语，常可省略，如 the place we visited。指人正式文体可用 whom，口语中 who 或省略更常见。省略的前提是从句已有主语而缺宾语；关系代词作主语时不能随便省略。visit 是及物动词，visit the city 不需额外加 to，但 go to the city 需要 to。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>This is the photograph that I took at the harbour.</p></blockquote><p>这是我在港口拍的照片。</p><p>That 在从句 I took 中作宾语，可在这一限制性从句中省略；at the harbour 表拍照地点。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>met 后不再补 him；先行词 guide 已通过关系从句充当 met 的宾语。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“This is the photograph that I took at the harbour.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>This is the photograph that I took at the harbour. The guide we met in Perth spoke three languages.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“讲述旅行中见到的人与事物”写两至三句，再读给同伴听。至少使用一次关系代词作宾语，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>That 在从句 I took 中作宾语，可在这一限制性从句中省略；at the harbour 表拍照地点。 The guide 是先行词；we met 中 we 为主语，被省略的关系代词是 met 的宾语；spoke 是主句谓语。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>改正：the photograph that I took it.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the photograph that I took</p><p><strong>解析：</strong> 按本课规则判断：在限制性定语从句中，关系代词若作宾语，常可省略，如 the place we visited。指人正式文体可用 whom，口语中 who 或省略更常见。省略的前提是从句已有主语而缺宾语；关系代词作主语时不能随便省略。visit 是及物动词，visit the city 不需额外加 to，但 go to the city 需要 to。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“这是我在港口拍的照片。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> This is the photograph that I took at the harbour.</p><p><strong>解析：</strong> That 在从句 I took 中作宾语，可在这一限制性从句中省略；at the harbour 表拍照地点。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：The guide we met in Perth spoke three languages.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 我们在珀斯遇到的导游会说三种语言。</p><p><strong>解析：</strong> The guide 是先行词；we met 中 we 为主语，被省略的关系代词是 met 的宾语；spoke 是主句谓语。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：关系代词作宾语。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-06/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-06/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-06/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-123">上一课</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-125">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=t(n,[["render",h]]);export{u as __pageData,g as default};
